"""page_builder.py — модульная сборка product-page HTML из готовых блоков.

Архитектура:
- BASE_CSS — целиком CSS из docs/claude-prompts/template.html (без topbar/footer).
- THEME_TOKENS_TPL — `:root` с f-string-плейсхолдерами под 5-цветную палитру.
- BASIC_JS — IntersectionObserver для `.reveal`-анимаций (~300 байт).
- MODULES — словарь {module_id → {kind, description, slots, html}}.
  Каждый html-фрагмент содержит `{SLOT}` плейсхолдеры. Подставляются через
  `str.format_map(SafeDict)` (отсутствующие ключи → пустая строка).
- MODULE_CATALOG — компактное описание для промпта Opus, без html
  (передавать LLM весь html — лишние токены).

Использование (см. также демо `python pipeline/page_builder.py`):
    from page_builder import assemble_page, MODULE_CATALOG
    layout = ["hero1", "m21", "m32", "m41", "m51"]
    slot_values = [
        {"KICKER": "Edition 01", "H1": "Take a closer look", "P": "...", "IMG_URL": "...", "IMG_ALT": "..."},
        {"KICKER": "Story · I", "H3": "It started in a clinic", "P": "...", "IMG_URL": "...", "IMG_ALT": "..."},
        ...,
    ]
    palette = {"brand_1": "#ff9c70", "brand_2": "#aac9f5", "brand_3": "#a6d8be",
               "brand_soft": "#ffe9d6", "brand_deep": "#ffc8b0"}
    html_str = assemble_page(layout, slot_values, palette)

Колab-friendly: один файл, скачивается в рантайме через raw URL (см. ноутбук).
"""

from __future__ import annotations

from string import Template
from typing import Any


# ============================================================
# Theme tokens — :root CSS под 5-цветную палитру.
# Использует string.Template ($brand_1), а не str.format ({...}),
# чтобы CSS-фигурные не интерпретировались как плейсхолдеры.
# ============================================================
THEME_TOKENS_TPL = ':root{\n  --brand-1: $brand_1;\n  --brand-2: $brand_2;\n  --brand-3: $brand_3;\n  --brand-soft: $brand_soft;\n  --brand-deep: $brand_deep;\n  --bg:#ffffff; --bg-2:#f5f5f7;\n  --ink:#1d1d1f; --ink-2:#424245; --ink-3:#6e6e73; --ink-4:#86868b;\n  --line:rgba(0,0,0,.08); --link:#0066cc;\n  --grad-peach: linear-gradient(180deg, var(--brand-soft) 0%, var(--brand-deep) 50%, var(--brand-1) 100%);\n  --grad-sky:   linear-gradient(180deg, #d8eaff 0%, #c3dcff 50%, var(--brand-2) 100%);\n  --grad-mint:  linear-gradient(180deg, #d9efe5 0%, #c2e6d3 50%, var(--brand-3) 100%);\n  --grad-sand:  linear-gradient(180deg, #f5ede1 0%, #ebdcc3 50%, #ddc7a3 100%);\n  --grad-lilac: linear-gradient(180deg, #e8e0f5 0%, #d4c5ec 50%, #b8a4d8 100%);\n  --gap-module:160px; --gap-variant:96px; --gap-head:80px;\n}'


# ============================================================
# Reveal-on-scroll IntersectionObserver
# ============================================================
BASIC_JS = "// ===== Reveal on scroll =====\nconst io = new IntersectionObserver((entries)=>{\n  entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });\n}, {threshold:.1, rootMargin:'0px 0px -8% 0px'});\ndocument.querySelectorAll('.reveal, .words, .mask').forEach(el=>io.observe(el));"


