class _SafeDict(dict):
    """Миссинг-ключи в format_map → пустая строка, не KeyError."""

    def __missing__(self, key: str) -> str:
        return ""


def render_module(module_id: str, slots: dict[str, str]) -> str:
    """Подставить slot-значения в html-шаблон конкретного модуля.

    Бросает KeyError если module_id не в каталоге.
    """
    tpl = _MODULE_HTML[module_id]
    safe = _SafeDict({k: ("" if v is None else str(v)) for k, v in slots.items()})
    return tpl.format_map(safe)


def render_theme_tokens(palette: dict[str, str]) -> str:
    """:root{...} CSS со встроенной палитрой.

    palette ключи: brand_1, brand_2, brand_3, brand_soft, brand_deep.
    Любой отсутствующий — заменится дефолтом из шаблона.
    """
    defaults = {
        "brand_1": "#ff9c70", "brand_2": "#aac9f5", "brand_3": "#a6d8be",
        "brand_soft": "#ffe9d6", "brand_deep": "#ffc8b0",
    }
    merged = {**defaults, **{k: v for k, v in (palette or {}).items() if v}}
    return Template(THEME_TOKENS_TPL).safe_substitute(**merged)


def validate_layout(layout: list[str]) -> list[str]:
    """Список module_id, которых нет в каталоге."""
    return [m for m in layout if m not in _MODULE_HTML]


def assemble_page(
    layout: list[str],
    slot_values: list[dict[str, str]],
    palette: dict[str, str] | None = None,
    *,
    language: str = "en",
    title: str = "",
) -> str:
    """Собрать финальный HTML страницы продукта из выбранных модулей.

    layout      — порядок модулей (могут повторяться)
    slot_values — список slot-словарей, параллельный layout
    palette     — 5 hex-цветов (brand_1..brand_deep). None → дефолтная палитра.
    language    — атрибут <html lang=...>
    title       — <title> тега (можно пустую — пользователь делает отдельно SEO meta)

    Никаких topbar / footer / shipping / returns не добавляется. Эти блоки
    обеспечиваются темой Shopify.
    """
    if len(layout) != len(slot_values):
        raise ValueError(
            f"len(layout)={len(layout)} != len(slot_values)={len(slot_values)}"
        )
    bad = validate_layout(layout)
    if bad:
        raise ValueError(f"unknown module ids: {bad}; available: {sorted(_MODULE_HTML)}")

    body_parts = [render_module(mid, slots) for mid, slots in zip(layout, slot_values)]
    body = "\n\n".join(body_parts)

    return (
        "<!doctype html>\n"
        f'<html lang="{language}">\n'
        "<head>\n"
        '<meta charset="utf-8" />\n'
        '<meta name="viewport" content="width=device-width,initial-scale=1" />\n'
        f"<title>{title}</title>\n"
        '<link rel="preconnect" href="https://fonts.googleapis.com">\n'
        '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n'
        '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Fraunces:ital,wght@0,300;0,400;0,500;1,300;1,400&display=swap" rel="stylesheet">\n'
        "<style>\n"
        + render_theme_tokens(palette or {}) + "\n"
        + BASE_CSS + "\n"
        "</style>\n"
        "</head>\n"
        "<body>\n"
        + body + "\n"
        f"<script>{BASIC_JS}</script>\n"
        "</body>\n"
        "</html>\n"
    )


# ============================================================
# Helper: pre-render списков для слотов (BADGES_HTML и т.п.)
# ============================================================
def render_badges(items: list[str], solid_first: int = 2) -> str:
    """Список строк → HTML <span class='badge'> элементы.

    solid_first — первые N бейджей рендерятся class='badge solid' (выделение).
    """
    out = []
    for i, t in enumerate(items):
        cls = "badge solid" if i < solid_first else "badge"
        out.append(f'<span class="{cls}">{t}</span>')
    return "".join(out)




# ============================================================
# BASE_CSS — целиком CSS из template.html (минус topbar/footer/:root)
# Большой блок (~84 KB) — намеренно в конце файла, не мешает чтению логики.
# ============================================================
BASE_CSS = '\n  /* ============================================================ */\n  /* ====================== THEME TOKENS ======================= */\n  /* AI AGENTS: change these 5 values to re-skin the whole page. */\n  /* ============================================================ */\n  \n  *{box-sizing:border-box;margin:0;padding:0}\n  html{scroll-behavior:auto;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}\n  html,body{\n    background:#fff;color:var(--ink);\n    font-family:\'Inter\',\'SF Pro Display\',-apple-system,BlinkMacSystemFont,sans-serif;\n    overflow-x:hidden;\n    font-feature-settings:"ss01","cv11";\n    letter-spacing:-.011em;\n  }\n  img{display:block;max-width:100%}\n  a{color:inherit;text-decoration:none}\n  button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}\n\n  .container{max-width:1240px;margin:0 auto;padding:0 24px}\n  .container-narrow{max-width:980px;margin:0 auto;padding:0 24px}\n\n  /* ===================== HERO ===================== */\n  .hero{\n    min-height:100vh;padding:160px 24px 80px;text-align:center;position:relative;\n    display:flex;flex-direction:column;align-items:center;justify-content:center;\n    background:\n      radial-gradient(ellipse 1000px 600px at 50% 20%, rgba(255,200,176,.35), transparent 60%),\n      radial-gradient(ellipse 800px 500px at 50% 80%, rgba(195,220,255,.3), transparent 60%),\n      #fff;\n  }\n  .hero .eyebrow{\n    font-size:21px;font-weight:600;letter-spacing:-.018em;\n    background:linear-gradient(90deg,#ff9c70,#aac9f5,#a6d8be,#ff9c70);\n    background-size:300% 100%;\n    -webkit-background-clip:text;background-clip:text;color:transparent;\n    animation:hueShift 8s ease-in-out infinite;\n  }\n  @keyframes hueShift{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}\n  .hero h1{\n    margin-top:14px;font-size:clamp(64px,11vw,160px);font-weight:600;line-height:.94;letter-spacing:-.05em;\n    max-width:1200px;\n  }\n  .hero h1 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .hero .lead{margin-top:32px;font-size:24px;line-height:1.4;color:var(--ink-2);max-width:760px;font-weight:400;letter-spacing:-.012em}\n  .hero .cta-row{margin-top:48px;display:flex;gap:18px;justify-content:center;flex-wrap:wrap}\n  .hero .cta-row a{font-size:17px;font-weight:500}\n  .hero .cta-row .primary{background:var(--ink);color:#fff;padding:14px 28px;border-radius:999px;display:inline-flex;align-items:center;gap:6px}\n  .hero .cta-row .secondary{color:var(--link);display:inline-flex;align-items:center;gap:6px}\n  .hero .cta-row .secondary:hover{text-decoration:underline}\n  .hero .scroll-cue{position:absolute;bottom:40px;left:50%;transform:translateX(-50%);font-size:12px;color:var(--ink-3);display:flex;flex-direction:column;align-items:center;gap:8px;letter-spacing:.06em;text-transform:uppercase;animation:bobble 2s ease-in-out infinite}\n  .hero .scroll-cue .arrow{width:1px;height:40px;background:linear-gradient(180deg,var(--ink-3),transparent)}\n  @keyframes bobble{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(8px)}}\n\n  /* ===================== TOC GRID ===================== */\n  .toc-section{padding:120px 24px 80px}\n  .toc-grid{\n    display:grid;grid-template-columns:repeat(4,1fr);gap:8px;\n    max-width:1280px;margin:0 auto;\n  }\n  @media(max-width:1100px){.toc-grid{grid-template-columns:repeat(3,1fr)}}\n  @media(max-width:700px){.toc-grid{grid-template-columns:repeat(2,1fr)}}\n  .toc-card{\n    background:var(--bg-2);border-radius:18px;padding:22px;\n    display:flex;flex-direction:column;gap:14px;min-height:160px;\n    transition:transform .35s cubic-bezier(.2,.7,.2,1), background .25s;\n    position:relative;overflow:hidden;\n  }\n  .toc-card:hover{transform:translateY(-3px);background:#eaeaed}\n  .toc-card::after{content:"→";position:absolute;top:18px;right:20px;font-size:18px;color:var(--ink-4);transition:transform .3s, color .3s}\n  .toc-card:hover::after{transform:translate(4px,-4px);color:var(--ink)}\n  .toc-card .num{font-size:11px;letter-spacing:.18em;color:var(--ink-4);font-weight:600;text-transform:uppercase}\n  .toc-card .ttl{font-size:21px;font-weight:600;letter-spacing:-.018em;line-height:1.15;margin-top:auto}\n  .toc-card .ttl em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:400}\n  .toc-card .meta{font-size:11px;letter-spacing:.04em;color:var(--ink-3)}\n\n  /* ============================================================ */\n  /* ============== MODULE LAYOUT (AI-FRIENDLY) ================= */\n  /* Page structure for agents:                                    */\n  /*   <section class="module" id="mN">          ← one per chapter*/\n  /*     <div class="module-head"> … header … </div>              */\n  /*     <div class="variant"> … variant 1 … </div>               */\n  /*     <div class="variant"> … variant 2 … </div>               */\n  /*   </section>                                                  */\n  /* Spacing is automatic — do NOT add inline padding overrides.  */\n  /* ============================================================ */\n  .module{padding:var(--gap-module) 24px;position:relative}\n  .module + .module{padding-top:0}                  /* avoid stacking module gaps */\n  .module-head{max-width:1200px;margin:0 auto var(--gap-head);text-align:center}\n  .module-head .ix{font-size:17px;font-weight:600;color:var(--ink-2)}\n  .module-head .ix span{color:var(--ink-4)}\n  .module-head h2{margin-top:8px;font-size:clamp(48px,7vw,96px);font-weight:600;letter-spacing:-.04em;line-height:1}\n  .module-head h2 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .module-head .desc{margin:32px auto 0;font-size:21px;line-height:1.45;color:var(--ink-2);max-width:680px;letter-spacing:-.01em}\n\n  /* Each variant is a child of .module, consistently spaced */\n  .variant{max-width:1280px;margin:0 auto}\n  .variant + .variant{margin-top:var(--gap-variant)}\n  /* full-bleed variants (scroll-driven hero stages) escape the max-width */\n  .variant.bleed{max-width:none;padding:0;margin-left:0;margin-right:0}\n  .variant.bleed + .variant{margin-top:var(--gap-variant)}\n\n  .variant-label{display:none}                       /* hidden by default */\n  /* legacy alias for older content */\n  .variant-block{max-width:1280px;margin:0 auto}\n  .variant-block + .variant-block{margin-top:var(--gap-variant)}\n\n  /* ===================== REVEAL HELPERS ===================== */\n  /* base reveal — fade up */\n  .reveal{opacity:0;transform:translateY(40px);transition:opacity 1s cubic-bezier(.2,.7,.2,1), transform 1s cubic-bezier(.2,.7,.2,1)}\n  .reveal.in{opacity:1;transform:none}\n  .delay-1{transition-delay:.1s}\n  .delay-2{transition-delay:.2s}\n  .delay-3{transition-delay:.3s}\n  .delay-4{transition-delay:.4s}\n\n  /* word-by-word reveal */\n  .words .word{display:inline-block;opacity:0;transform:translateY(.4em);transition:opacity .8s cubic-bezier(.2,.7,.2,1), transform .8s cubic-bezier(.2,.7,.2,1)}\n  .words.in .word{opacity:1;transform:none}\n  .words.in .word:nth-child(1){transition-delay:.05s}\n  .words.in .word:nth-child(2){transition-delay:.13s}\n  .words.in .word:nth-child(3){transition-delay:.21s}\n  .words.in .word:nth-child(4){transition-delay:.29s}\n  .words.in .word:nth-child(5){transition-delay:.37s}\n  .words.in .word:nth-child(6){transition-delay:.45s}\n  .words.in .word:nth-child(7){transition-delay:.53s}\n  .words.in .word:nth-child(8){transition-delay:.61s}\n  .words.in .word:nth-child(9){transition-delay:.69s}\n  .words.in .word:nth-child(10){transition-delay:.77s}\n\n  /* mask reveal — line slides up from below */\n  .mask{display:inline-block;overflow:hidden;vertical-align:bottom;line-height:1.05;padding-bottom:.04em}\n  .mask > span{display:inline-block;transform:translateY(110%);transition:transform 1.1s cubic-bezier(.2,.7,.2,1)}\n  .mask.in > span,.in .mask > span{transform:none}\n  .mask.d2 > span{transition-delay:.12s}\n  .mask.d3 > span{transition-delay:.24s}\n  .mask.d4 > span{transition-delay:.36s}\n\n  /* ===================== SCROLL-DRIVEN HERO STAGES ===================== */\n  /* "Take a closer look" style — large image scales/transforms by scroll */\n  .stage{\n    position:relative;height:300vh;\n  }\n  .stage .pin{\n    position:sticky;top:0;height:100vh;display:flex;align-items:center;justify-content:center;\n    overflow:hidden;\n  }\n\n  /* ===================== M1.1 — ROUNDED HERO IMAGE THAT SCALES OUT ===================== */\n  .m11{\n    background:\n      radial-gradient(ellipse 800px 500px at 50% 0%, rgba(255,200,176,.35), transparent 60%),\n      #fff;\n  }\n  .m11 .pin{flex-direction:column;gap:32px}\n  .m11 .img-frame{\n    position:relative;width:80vw;height:60vh;max-width:1200px;\n    border-radius:48px;overflow:hidden;\n    background:#1d1d1f;\n    transform:scale(.65);\n    transition:transform .15s linear, border-radius .15s linear;\n  }\n  .m11 .img-frame img{width:100%;height:100%;object-fit:cover;transform:scale(1.1);opacity:.85}\n  .m11 .floating-text{position:absolute;text-align:center;color:#fff;padding:0 48px;pointer-events:none;width:100%}\n  .m11 .floating-text .ey{font-size:14px;font-weight:600;letter-spacing:-.01em;background:linear-gradient(90deg,#ffd6c2,#aac9f5);-webkit-background-clip:text;background-clip:text;color:transparent}\n  .m11 .floating-text h3{margin-top:12px;font-size:clamp(48px,7vw,108px);font-weight:600;line-height:.96;letter-spacing:-.04em}\n  .m11 .floating-text h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n\n  /* ===================== M1.2 — TYPE-SPLIT HERO ===================== */\n  .m12{padding:160px 24px;background:linear-gradient(180deg,#fff,#fafafa)}\n  .m12 .row{display:grid;grid-template-columns:1.1fr 1fr;gap:80px;max-width:1280px;margin:0 auto;align-items:center}\n  .m12 .copy h3{font-size:clamp(48px,6.5vw,96px);font-weight:600;letter-spacing:-.04em;line-height:.98}\n  .m12 .copy h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m12 .copy .ix{font-size:17px;color:var(--ink-3);font-weight:500;margin-bottom:18px}\n  .m12 .copy .desc{margin-top:32px;font-size:19px;line-height:1.5;color:var(--ink-2);max-width:520px}\n  .m12 .copy .stats{margin-top:40px;display:grid;grid-template-columns:1fr 1fr;gap:32px;border-top:1px solid var(--line);padding-top:32px}\n  .m12 .copy .stat .v{font-size:48px;font-weight:600;letter-spacing:-.025em;line-height:1}\n  .m12 .copy .stat .v em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:400;color:var(--ink-3)}\n  .m12 .copy .stat .l{margin-top:6px;font-size:13px;color:var(--ink-3);letter-spacing:.06em}\n  .m12 .photo{position:relative;aspect-ratio:4/5;border-radius:32px;overflow:hidden;background:#f5f5f7}\n  .m12 .photo img{width:100%;height:100%;object-fit:cover;transform:scale(1.1);transition:transform 2s cubic-bezier(.2,.7,.2,1)}\n  .m12.in .photo img{transform:scale(1)}\n  @media(max-width:900px){.m12 .row{grid-template-columns:1fr;gap:48px}}\n\n  /* ===================== M1.3 — BIG QUOTE CENTERED ===================== */\n  .m13{padding:200px 24px;text-align:center;background:#fff}\n  .m13 q{\n    display:block;font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(40px,5.5vw,80px);\n    line-height:1.08;letter-spacing:-.025em;max-width:1100px;margin:0 auto;color:var(--ink);\n    quotes:"«" "»";\n  }\n  .m13 q em{font-style:italic}\n  .m13 .sig{margin-top:64px;font-size:14px;color:var(--ink-3);letter-spacing:.06em}\n  .m13 .sig strong{color:var(--ink);font-weight:600}\n\n  /* ===================== M1.4 — FLOATING IMAGES ===================== */\n  .m14{position:relative;min-height:90vh;padding:120px 24px;display:flex;align-items:center;justify-content:center;overflow:hidden}\n  .m14 .center{text-align:center;position:relative;z-index:5;max-width:760px;padding:0 24px}\n  .m14 .center .ey{font-size:17px;font-weight:600;color:var(--ink-2);margin-bottom:14px}\n  .m14 .center h3{font-size:clamp(48px,6.5vw,84px);font-weight:600;letter-spacing:-.035em;line-height:.98}\n  .m14 .center h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m14 .center .lead{margin-top:24px;font-size:19px;line-height:1.5;color:var(--ink-2);max-width:540px;margin-left:auto;margin-right:auto}\n  .m14 .float{position:absolute;border-radius:24px;overflow:hidden;background:#fff;box-shadow:0 30px 60px rgba(29,29,31,.1)}\n  .m14 .float img{width:100%;height:100%;object-fit:cover}\n  .m14 .float.f1{width:200px;height:240px;top:8%;left:10%;animation:fl1 9s ease-in-out infinite}\n  .m14 .float.f2{width:180px;height:180px;border-radius:50%;top:14%;right:12%;animation:fl2 10s ease-in-out infinite}\n  .m14 .float.f3{width:220px;height:200px;bottom:10%;left:14%;animation:fl3 11s ease-in-out infinite}\n  .m14 .float.f4{width:170px;height:210px;bottom:14%;right:14%;animation:fl4 12s ease-in-out infinite}\n  @keyframes fl1{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-22px) rotate(-1deg)}}\n  @keyframes fl2{0%,100%{transform:translateY(0) rotate(2deg)}50%{transform:translateY(-26px) rotate(-2deg)}}\n  @keyframes fl3{0%,100%{transform:translateY(0) rotate(2deg)}50%{transform:translateY(-18px) rotate(4deg)}}\n  @keyframes fl4{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-22px) rotate(-1deg)}}\n  @media(max-width:900px){.m14 .float{display:none}}\n\n  /* ===================== M1.5 — VIDEO LOOP HERO ===================== */\n  .m15{\n    position:relative;height:90vh;min-height:600px;\n    border-radius:32px;overflow:hidden;margin:0 24px;\n    background:#000;\n  }\n  .m15 .bg{\n    position:absolute;inset:0;\n    background:\n      radial-gradient(circle at 30% 40%, rgba(255,156,112,.45), transparent 50%),\n      radial-gradient(circle at 70% 60%, rgba(170,201,245,.4), transparent 60%),\n      linear-gradient(135deg,#1a1a1f,#2a1f1a);\n    animation:moveBg 24s ease-in-out infinite alternate;\n  }\n  @keyframes moveBg{from{transform:scale(1) translate(0,0)}to{transform:scale(1.15) translate(-30px,-30px)}}\n  .m15 .copy{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#fff;padding:48px}\n  .m15 .copy .ey{font-size:14px;font-weight:600;letter-spacing:.06em;color:rgba(255,255,255,.7);text-transform:uppercase}\n  .m15 .copy h3{margin-top:24px;font-size:clamp(48px,7vw,108px);font-weight:600;letter-spacing:-.04em;line-height:.98}\n  .m15 .copy h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m15 .copy .play{margin-top:48px;width:72px;height:72px;border-radius:50%;background:rgba(255,255,255,.95);color:var(--ink);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:transform .25s}\n  .m15 .copy .play:hover{transform:scale(1.08)}\n\n  /* ===================== M2 — STORY ===================== */\n  .m2-bg{background:linear-gradient(180deg,#fff,#fafafa)}\n  .story-row{display:grid;grid-template-columns:1fr 1fr;gap:0;border-radius:32px;overflow:hidden;background:#fff;min-height:560px;box-shadow:0 30px 80px rgba(29,29,31,.04)}\n  .story-row .img{position:relative;background:var(--bg-2);overflow:hidden}\n  .story-row .img img{width:100%;height:100%;object-fit:cover;transform:scale(1.15);transition:transform 2s cubic-bezier(.2,.7,.2,1)}\n  .story-row.in .img img{transform:scale(1)}\n  .story-row .copy{padding:80px 64px;display:flex;flex-direction:column;justify-content:center;gap:24px}\n  .story-row .ix{font-size:14px;font-weight:600;color:var(--ink-3);letter-spacing:.06em}\n  .story-row h3{font-size:clamp(36px,4.5vw,56px);font-weight:600;letter-spacing:-.028em;line-height:1.02}\n  .story-row h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .story-row p{font-size:19px;line-height:1.5;color:var(--ink-2)}\n  .story-row .arrow{display:inline-flex;align-items:center;gap:6px;color:var(--link);font-weight:500;font-size:17px;align-self:flex-start}\n  .story-row .arrow:hover{text-decoration:underline}\n  .story-mirror{grid-template-columns:1fr 1fr}\n  .story-mirror .img{order:2}\n  @media(max-width:900px){.story-row{grid-template-columns:1fr}.story-mirror .img{order:0}.story-row .copy{padding:48px 32px}}\n\n  /* M2.3 — sticky scroll story */\n  .m23{display:grid;grid-template-columns:1fr 1fr;gap:80px;max-width:1280px;margin:0 auto;padding:0 24px;align-items:start}\n  .m23 .sticky{position:sticky;top:80px;align-self:start;padding:0}\n  .m23 .sticky h3{font-size:clamp(40px,5vw,72px);font-weight:600;letter-spacing:-.03em;line-height:1}\n  .m23 .sticky h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m23 .sticky .ix{font-size:14px;font-weight:600;color:var(--ink-3);margin-bottom:18px}\n  .m23 .sticky .desc{margin-top:32px;font-size:19px;line-height:1.5;color:var(--ink-2);max-width:480px}\n  .m23 .sticky .ind{margin-top:48px;display:flex;flex-direction:column;gap:14px}\n  .m23 .sticky .ind .row{display:grid;grid-template-columns:32px 1fr;gap:18px;align-items:center;font-size:17px;color:var(--ink-3);transition:color .4s}\n  .m23 .sticky .ind .row .num{font-size:13px;font-weight:600;letter-spacing:.06em;color:var(--ink-4)}\n  .m23 .sticky .ind .row.on{color:var(--ink);font-weight:500}\n  .m23 .sticky .ind .row.on .num{color:var(--ink)}\n  .m23 .scroll{display:flex;flex-direction:column;gap:32px;padding:0}\n  .m23 .scroll .pic{aspect-ratio:4/5;border-radius:24px;overflow:hidden;position:relative;transition:transform .6s, box-shadow .6s}\n  .m23 .scroll .pic.focused{transform:scale(1.02);box-shadow:0 30px 80px rgba(29,29,31,.12)}\n  .m23 .scroll .pic img{width:100%;height:100%;object-fit:cover}\n  .m23 .scroll .pic .lbl{position:absolute;left:18px;bottom:18px;background:rgba(255,255,255,.9);backdrop-filter:blur(10px);font-size:12px;font-weight:500;padding:6px 12px;border-radius:8px;letter-spacing:-.005em}\n  @media(max-width:900px){.m23{grid-template-columns:1fr;gap:32px}.m23 .sticky{position:static}}\n\n  /* M2.4 — scroll-driven horizontal split */\n  .m24{position:relative;min-height:140vh}\n  .m24 .pin{position:sticky;top:0;height:100vh;display:flex;align-items:center;justify-content:center;overflow:hidden}\n  .m24 .stage-inner{position:relative;width:90vw;max-width:1200px;height:70vh;display:flex;gap:24px}\n  .m24 .panel{flex:1;border-radius:32px;overflow:hidden;position:relative;background:#1a1a1f;transition:flex .8s cubic-bezier(.2,.7,.2,1)}\n  .m24 .panel img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.8}\n  .m24 .panel .label{position:absolute;left:24px;bottom:24px;color:#fff;font-size:14px;font-weight:600;letter-spacing:.06em;text-transform:uppercase}\n  .m24 .panel .label small{display:block;font-weight:400;opacity:.7;text-transform:none;letter-spacing:0;margin-top:4px;font-size:13px}\n  .m24 .text-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;color:#fff;padding:48px;pointer-events:none;z-index:2}\n  .m24 .text-overlay h3{font-size:clamp(40px,5.5vw,80px);font-weight:600;letter-spacing:-.03em;line-height:1;max-width:900px}\n  .m24 .text-overlay h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m24.expand .panel.left{flex:3}\n  .m24.expand .panel.right{flex:.7}\n\n  /* M2.5 — full-bleed hero with overlay card */\n  .m25{position:relative;min-height:90vh;border-radius:32px;overflow:hidden;margin:0 24px;background:#1a1a1f}\n  .m25 img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.7;transform:scale(1.08);transition:transform 3s cubic-bezier(.2,.7,.2,1)}\n  .m25.in img{transform:scale(1)}\n  .m25 .card{position:absolute;left:48px;bottom:48px;max-width:520px;padding:40px 44px;background:rgba(255,255,255,.9);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-radius:24px}\n  .m25 .card .ix{font-size:14px;font-weight:600;color:var(--ink-2)}\n  .m25 .card h3{margin-top:14px;font-size:36px;font-weight:600;letter-spacing:-.025em;line-height:1.08}\n  .m25 .card h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m25 .card p{margin-top:14px;font-size:17px;line-height:1.5;color:var(--ink-2)}\n  .m25 .card .cta{margin-top:20px;display:inline-flex;align-items:center;gap:6px;color:var(--link);font-weight:500;font-size:17px}\n  .m25 .badge{position:absolute;right:48px;top:48px;background:rgba(255,255,255,.9);backdrop-filter:blur(20px);font-size:13px;font-weight:600;padding:8px 14px;border-radius:999px;letter-spacing:-.005em}\n\n  /* ============================================================ */\n  /* ============== HERO ALT — 5 hero variations ================= */\n  /* ============================================================ */\n  .hero-alt{position:relative;min-height:100vh;display:flex;align-items:center;overflow:hidden;border-radius:32px;margin:24px}\n\n  /* H.1 — Editorial split: huge serif + product photo */\n  .hero1{background:#fdf6ee;padding:80px 56px;display:grid;grid-template-columns:1.2fr 1fr;gap:48px;align-items:center}\n  .hero1 .ix{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#a06640;font-weight:700}\n  .hero1 h1{margin-top:18px;font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(64px,9vw,140px);line-height:.92;letter-spacing:-.04em}\n  .hero1 h1 em{font-style:italic;color:var(--brand-1)}\n  .hero1 p{margin-top:28px;font-size:19px;line-height:1.55;color:var(--ink-2);max-width:440px}\n  .hero1 .ctas{margin-top:32px;display:flex;gap:14px;flex-wrap:wrap}\n  .hero1 .ctas a{padding:14px 22px;border-radius:999px;font-size:14px;font-weight:600;letter-spacing:-.005em;text-decoration:none}\n  .hero1 .ctas .p{background:var(--ink);color:#fff}\n  .hero1 .ctas .s{color:var(--ink);border:1px solid var(--line)}\n  .hero1 .photo{aspect-ratio:4/5;border-radius:24px;overflow:hidden;background:#1a1a1f}\n  .hero1 .photo img{width:100%;height:100%;object-fit:cover;transform:scale(1.1);transition:transform 2.4s cubic-bezier(.2,.7,.2,1)}\n  .hero1.in .photo img{transform:scale(1)}\n  @media(max-width:900px){.hero1{grid-template-columns:1fr;padding:48px 28px}}\n\n  /* H.2 — Cinematic dark with full-bleed image */\n  .hero2{background:#0e0e10;color:#fff;padding:0}\n  .hero2 .bg{position:absolute;inset:0}\n  .hero2 .bg img{width:100%;height:100%;object-fit:cover;opacity:.55;transform:scale(1.1);transition:transform 4s cubic-bezier(.2,.7,.2,1)}\n  .hero2.in .bg img{transform:scale(1)}\n  .hero2::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.2) 0%,rgba(0,0,0,.65) 100%)}\n  .hero2 .copy{position:relative;z-index:2;padding:80px 56px;max-width:920px}\n  .hero2 .ix{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.7);font-weight:600}\n  .hero2 .ix .dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--brand-1);margin-right:8px;box-shadow:0 0 12px var(--brand-1)}\n  .hero2 h1{margin-top:24px;font-size:clamp(56px,8vw,128px);font-weight:600;letter-spacing:-.04em;line-height:.95}\n  .hero2 h1 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .hero2 p{margin-top:32px;font-size:19px;line-height:1.55;color:rgba(255,255,255,.78);max-width:480px}\n  .hero2 .meta{position:absolute;left:56px;bottom:48px;right:56px;z-index:2;display:flex;justify-content:space-between;align-items:flex-end;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.6);font-weight:600}\n  .hero2 .meta strong{color:#fff;font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;text-transform:none;letter-spacing:-.01em;font-size:24px;display:block}\n  @media(max-width:900px){.hero2 .copy{padding:56px 28px}.hero2 .meta{left:28px;right:28px;flex-direction:column;gap:18px;align-items:flex-start}}\n\n  /* H.3 — Marquee tagline (animated horizontal type) */\n  .hero3{background:#fff;padding:80px 0;flex-direction:column;justify-content:center;align-items:stretch}\n  .hero3 .ix{padding:0 56px;font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-3);font-weight:700;text-align:center}\n  .hero3 .marquee{margin-top:32px;overflow:hidden;white-space:nowrap;mask-image:linear-gradient(90deg,transparent 0,#000 8%,#000 92%,transparent 100%);-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 8%,#000 92%,transparent 100%)}\n  .hero3 .marquee .track{display:inline-flex;align-items:center;gap:48px;animation:hero3scroll 38s linear infinite;font-family:\'Fraunces\',serif;font-size:clamp(64px,10vw,160px);font-weight:300;letter-spacing:-.035em;line-height:1}\n  .hero3 .marquee .track em{font-style:italic;color:var(--brand-1)}\n  .hero3 .marquee .track span{display:inline-flex;align-items:center;gap:48px}\n  .hero3 .marquee .dot{width:14px;height:14px;border-radius:50%;background:var(--brand-1);flex-shrink:0}\n  @keyframes hero3scroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n  .hero3 .body{padding:48px 56px 0;display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:end}\n  .hero3 .body p{font-size:18px;line-height:1.55;color:var(--ink-2);max-width:520px}\n  .hero3 .body .stats{display:flex;gap:36px;justify-content:flex-end}\n  .hero3 .body .stat{text-align:right}\n  .hero3 .body .stat .v{font-family:\'Fraunces\',serif;font-weight:300;font-style:italic;font-size:48px;letter-spacing:-.02em;color:var(--ink);line-height:1}\n  .hero3 .body .stat .l{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3);font-weight:700;margin-top:6px}\n  @media(max-width:900px){.hero3 .body{grid-template-columns:1fr;padding:32px 28px 0}.hero3 .body .stats{justify-content:flex-start}}\n\n  /* H.4 — Catalog index — table of contents as hero */\n  .hero4{background:linear-gradient(180deg,#fff 0%,#fdf6ee 100%);padding:80px 56px;display:grid;grid-template-columns:1fr 1.3fr;gap:64px;align-items:center}\n  .hero4 .l .ix{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#a06640;font-weight:700}\n  .hero4 .l h1{margin-top:18px;font-size:clamp(56px,7vw,108px);font-weight:600;letter-spacing:-.04em;line-height:.95}\n  .hero4 .l h1 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .hero4 .l .meta{margin-top:32px;font-size:14px;color:var(--ink-3);letter-spacing:.04em}\n  .hero4 .l .meta strong{color:var(--ink);font-weight:700;font-family:\'Fraunces\',serif;font-weight:300;font-style:italic;font-size:32px;display:block;letter-spacing:-.01em;margin-top:6px}\n  .hero4 .toc{display:flex;flex-direction:column;gap:0;border-top:1px solid var(--line)}\n  .hero4 .toc a{display:grid;grid-template-columns:60px 1fr auto;gap:24px;padding:18px 8px;border-bottom:1px solid var(--line);text-decoration:none;color:var(--ink);align-items:center;transition:background .3s,padding .4s}\n  .hero4 .toc a:hover{background:rgba(255,156,112,.08);padding-left:18px}\n  .hero4 .toc a .n{font-family:\'Fraunces\',serif;font-weight:300;font-style:italic;color:var(--brand-1);font-size:22px;letter-spacing:-.01em}\n  .hero4 .toc a .t{font-size:18px;font-weight:600;letter-spacing:-.012em}\n  .hero4 .toc a .t em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .hero4 .toc a .arr{font-size:14px;color:var(--ink-3);transition:transform .3s,color .3s}\n  .hero4 .toc a:hover .arr{color:var(--brand-1);transform:translateX(4px)}\n  @media(max-width:900px){.hero4{grid-template-columns:1fr;padding:48px 28px}}\n\n  /* H.5 — Animated counter / kinetic typography */\n  .hero5{background:#0e0e10;color:#fff;padding:0;text-align:center;flex-direction:column;justify-content:center}\n  .hero5::before{content:"";position:absolute;inset:-50% 30%;background:radial-gradient(circle,var(--brand-1),transparent 60%);opacity:.18;filter:blur(80px);animation:hero5pulse 8s ease-in-out infinite}\n  @keyframes hero5pulse{0%,100%{transform:scale(1);opacity:.18}50%{transform:scale(1.2);opacity:.28}}\n  .hero5 .ix{position:relative;font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:rgba(255,255,255,.55);font-weight:600}\n  .hero5 .lines{position:relative;margin-top:32px;display:flex;flex-direction:column;gap:0;align-items:center}\n  .hero5 .lines .line{display:flex;align-items:baseline;gap:24px;font-size:clamp(48px,7vw,108px);font-weight:600;letter-spacing:-.04em;line-height:1}\n  .hero5 .lines .line em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .hero5 .lines .line .num{font-family:\'Fraunces\',serif;font-weight:300;font-style:italic;color:var(--brand-1);font-variant-numeric:tabular-nums;min-width:1.6em;text-align:right}\n  .hero5 .sub{position:relative;margin-top:48px;font-size:18px;line-height:1.5;color:rgba(255,255,255,.65);max-width:520px;margin-left:auto;margin-right:auto}\n  .hero5 .ctas{position:relative;margin-top:36px;display:flex;gap:14px;justify-content:center}\n  .hero5 .ctas a{padding:14px 22px;border-radius:999px;font-size:14px;font-weight:600;text-decoration:none}\n  .hero5 .ctas .p{background:var(--brand-1);color:#1f1411}\n  .hero5 .ctas .s{color:#fff;border:1px solid rgba(255,255,255,.2)}\n\n  /* ============================================================ */\n  /* ============== EXTRA VARIANTS — M1..M5 (×3 each) ============ */\n  /* ============================================================ */\n\n  /* ----- M1.6 — Half-bleed product card with badge stack ----- */\n  .m16{display:grid;grid-template-columns:1.05fr 1fr;gap:0;background:#0e0e10;color:#fff;border-radius:32px;overflow:hidden;margin:0 24px;min-height:640px}\n  .m16 .img{position:relative;overflow:hidden}\n  .m16 .img img{width:100%;height:100%;object-fit:cover;transform:scale(1.1);transition:transform 2.4s cubic-bezier(.2,.7,.2,1)}\n  .m16.in .img img{transform:scale(1)}\n  .m16 .copy{padding:64px 56px;display:flex;flex-direction:column;justify-content:center;gap:28px}\n  .m16 .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.5);font-weight:600}\n  .m16 h3{font-size:clamp(44px,5vw,68px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .m16 h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .m16 p{font-size:18px;line-height:1.55;color:rgba(255,255,255,.72);max-width:440px}\n  .m16 .badges{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}\n  .m16 .badge{padding:8px 14px;border:1px solid rgba(255,255,255,.18);border-radius:999px;font-size:12px;letter-spacing:.06em;color:rgba(255,255,255,.85)}\n  .m16 .badge.solid{background:var(--brand-1);border-color:var(--brand-1);color:#1f1411;font-weight:600}\n  @media(max-width:900px){.m16{grid-template-columns:1fr}.m16 .copy{padding:40px 28px}}\n\n  /* ----- M1.7 — Split contrast (dark/light typography hero) ----- */\n  .m17{display:grid;grid-template-columns:1fr 1fr;border-radius:32px;overflow:hidden;margin:0 24px;min-height:560px}\n  .m17 .l,.m17 .r{padding:64px 48px;display:flex;flex-direction:column;justify-content:space-between}\n  .m17 .l{background:#0e0e10;color:#fff}\n  .m17 .r{background:#fdf6ee;color:var(--ink)}\n  .m17 .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;opacity:.6}\n  .m17 .big{font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(64px,9vw,140px);line-height:.92;letter-spacing:-.04em}\n  .m17 .big em{font-style:italic}\n  .m17 .l .big em{color:var(--brand-1)}\n  .m17 .r .big em{color:#a06640}\n  .m17 .foot{font-size:14px;line-height:1.5;max-width:300px;opacity:.7}\n  @media(max-width:900px){.m17{grid-template-columns:1fr}}\n\n  /* ----- M1.8 — Product on plinth with tape-measure stats ----- */\n  .m18{padding:80px 24px;background:#fdf6ee;border-radius:32px;margin:0 24px;text-align:center;position:relative;overflow:hidden}\n  .m18 .pedestal{position:relative;display:inline-block;margin:0 auto}\n  .m18 .photo{width:280px;height:380px;background:#fff;border-radius:24px;overflow:hidden;box-shadow:0 30px 80px rgba(29,29,31,.18);position:relative;z-index:2}\n  .m18 .photo img{width:100%;height:100%;object-fit:cover}\n  .m18 .plinth{position:absolute;left:50%;bottom:-32px;transform:translateX(-50%);width:380px;height:80px;background:radial-gradient(ellipse at center,rgba(29,29,31,.16),transparent 70%);z-index:1}\n  .m18 h3{margin-top:64px;font-size:clamp(40px,4.6vw,60px);font-weight:600;letter-spacing:-.03em;line-height:1.05}\n  .m18 h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m18 .ticks{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;max-width:780px;margin:48px auto 0;padding:24px;background:#fff;border-radius:20px;box-shadow:0 10px 30px rgba(29,29,31,.06)}\n  .m18 .tick{padding:8px;border-right:1px solid var(--line);text-align:left}\n  .m18 .tick:last-child{border-right:none}\n  .m18 .tick .lbl{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3);font-weight:700}\n  .m18 .tick .v{font-family:\'Fraunces\',serif;font-weight:300;font-size:32px;letter-spacing:-.02em;color:var(--ink);margin-top:4px}\n  .m18 .tick .v em{font-style:normal;font-family:\'Inter\';font-size:14px;font-weight:500;color:var(--ink-3);margin-left:2px}\n  @media(max-width:760px){.m18 .ticks{grid-template-columns:repeat(2,1fr)}.m18 .tick:nth-child(2){border-right:none}}\n\n  /* ----- M2.7 — Annotated photo (callouts on image) ----- */\n  .m27{position:relative;border-radius:32px;overflow:hidden;margin:0 24px;background:#0e0e10;min-height:680px}\n  .m27 img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.85}\n  .m27::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.2) 0%,rgba(0,0,0,.6) 100%)}\n  .m27 .head{position:absolute;top:48px;left:48px;right:48px;z-index:2;color:#fff;display:flex;justify-content:space-between;align-items:flex-start}\n  .m27 .head .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.7);font-weight:600}\n  .m27 .head .ttl{font-family:\'Fraunces\',serif;font-weight:300;font-style:italic;font-size:32px;letter-spacing:-.02em;text-align:right;max-width:340px;line-height:1.15}\n  .m27 .note{position:absolute;z-index:3;color:#fff}\n  .m27 .note .pin{width:14px;height:14px;border-radius:50%;background:var(--brand-1);box-shadow:0 0 0 6px rgba(255,156,112,.25), 0 0 30px rgba(255,156,112,.6);position:relative}\n  .m27 .note .pin::before{content:"";position:absolute;top:7px;left:7px;width:1px;height:60px;background:rgba(255,255,255,.4)}\n  .m27 .note .lbl{margin-top:70px;font-size:11px;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--brand-1)}\n  .m27 .note p{margin-top:6px;font-size:15px;line-height:1.45;max-width:200px;color:rgba(255,255,255,.9)}\n  .m27 .n1{top:30%;left:18%}\n  .m27 .n2{top:45%;left:55%}\n  .m27 .n3{top:62%;left:30%}\n\n  /* ----- M2.8 — Stacked timeline rows ----- */\n  .m28{display:grid;gap:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);max-width:1200px;margin:0 auto}\n  .m28 .row{display:grid;grid-template-columns:120px 1fr 1.2fr;gap:32px;padding:40px 32px;border-bottom:1px solid var(--line);align-items:center;transition:background .4s}\n  .m28 .row:last-child{border-bottom:none}\n  .m28 .row:hover{background:#fdf6ee}\n  .m28 .row .yr{font-family:\'Fraunces\',serif;font-weight:300;font-style:italic;font-size:42px;letter-spacing:-.02em;color:var(--brand-1)}\n  .m28 .row .ttl{font-size:22px;font-weight:600;letter-spacing:-.014em;line-height:1.2}\n  .m28 .row .ttl em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m28 .row p{font-size:15px;line-height:1.55;color:var(--ink-2);max-width:520px}\n  @media(max-width:760px){.m28 .row{grid-template-columns:1fr;gap:8px;padding:28px 24px}.m28 .row .yr{font-size:32px}}\n\n  /* ----- M2.9 — Vertical fold-out story ----- */\n  .m29{max-width:760px;margin:0 auto;padding:0 24px}\n  .m29 .chapter{padding:48px 0;border-bottom:1px solid var(--line)}\n  .m29 .chapter:last-child{border-bottom:none}\n  .m29 .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-3);font-weight:700}\n  .m29 h3{margin-top:14px;font-size:36px;font-weight:600;letter-spacing:-.025em;line-height:1.1}\n  .m29 h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .m29 p{margin-top:18px;font-size:18px;line-height:1.6;color:var(--ink-2)}\n  .m29 .pull{margin-top:24px;padding-left:20px;border-left:3px solid var(--brand-1);font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;font-size:22px;line-height:1.4;color:var(--ink)}\n\n  /* ----- M3.5 — Exploded cross-section ----- */\n  .m35x{padding:80px 48px;background:#0e0e10;color:#fff;border-radius:32px;margin:0 24px;display:grid;grid-template-columns:1fr 1.1fr;gap:64px;align-items:center;min-height:640px}\n  .m35x .copy h3{font-size:clamp(40px,4.6vw,60px);font-weight:600;letter-spacing:-.03em;line-height:1.05}\n  .m35x .copy h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .m35x .copy .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.5);font-weight:700;margin-bottom:18px}\n  .m35x .copy p{margin-top:24px;font-size:17px;line-height:1.6;color:rgba(255,255,255,.72);max-width:440px}\n  .m35x .copy ul{margin-top:24px;display:flex;flex-direction:column;gap:14px;list-style:none;padding:0}\n  .m35x .copy li{display:flex;align-items:center;gap:14px;font-size:15px;color:rgba(255,255,255,.85)}\n  .m35x .copy li .n{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1);min-width:28px;font-size:20px}\n  .m35x .scene{position:relative;aspect-ratio:1;display:flex;align-items:center;justify-content:center}\n  .m35x .layer{position:absolute;border-radius:50%;border:1px solid rgba(255,255,255,.15);transition:transform 1.4s cubic-bezier(.2,.7,.2,1)}\n  .m35x .layer.l1{width:90%;height:90%}\n  .m35x .layer.l2{width:65%;height:65%;background:rgba(255,156,112,.06)}\n  .m35x .layer.l3{width:40%;height:40%;background:radial-gradient(circle,var(--brand-1),var(--brand-deep))}\n  .m35x.in .l1{transform:translate(-30px,-20px)}\n  .m35x.in .l2{transform:translate(20px,30px)}\n  .m35x.in .l3{transform:translate(-10px,-10px)}\n  .m35x .lbl-pin{position:absolute;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--brand-1);font-weight:700;display:flex;align-items:center;gap:8px}\n  .m35x .lbl-pin::before{content:"";width:24px;height:1px;background:var(--brand-1)}\n  .m35x .lbl-pin.p1{top:18%;right:6%}\n  .m35x .lbl-pin.p2{top:48%;left:0}\n  .m35x .lbl-pin.p3{bottom:18%;right:18%}\n  @media(max-width:900px){.m35x{grid-template-columns:1fr;padding:48px 28px}.m35x .scene{max-width:420px;margin:0 auto;width:100%}}\n\n  /* ----- M3.6 — Side-by-side comparison ----- */\n  .m36{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:0 24px}\n  .m36 .col{padding:48px 36px;border-radius:24px;display:flex;flex-direction:column;gap:20px}\n  .m36 .col.salon{background:#f4f0ea;color:var(--ink-2)}\n  .m36 .col.lumea{background:#0e0e10;color:#fff}\n  .m36 .col .ix{font-size:11px;letter-spacing:.2em;text-transform:uppercase;font-weight:700;opacity:.6}\n  .m36 .col h3{font-size:32px;font-weight:600;letter-spacing:-.022em;line-height:1.05}\n  .m36 .col.lumea h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .m36 .col ul{list-style:none;padding:0;display:flex;flex-direction:column;gap:14px;margin-top:8px}\n  .m36 .col li{display:flex;gap:12px;font-size:15px;line-height:1.5}\n  .m36 .col li::before{content:"—";opacity:.4}\n  .m36 .col.lumea li::before{content:"✓";color:var(--brand-1);opacity:1}\n  .m36 .col .price{margin-top:auto;padding-top:24px;border-top:1px solid currentColor;border-color:rgba(0,0,0,.1);font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;font-size:24px;letter-spacing:-.01em;display:flex;justify-content:space-between;align-items:baseline}\n  .m36 .col.lumea .price{border-color:rgba(255,255,255,.15)}\n  .m36 .col .price small{font-family:\'Inter\';font-style:normal;font-size:11px;letter-spacing:.16em;text-transform:uppercase;font-weight:700;opacity:.6}\n  @media(max-width:900px){.m36{grid-template-columns:1fr}}\n\n  /* ----- M3.7 — Animated metric ribbon ----- */\n  .m37{padding:80px 48px;background:#fdf6ee;border-radius:32px;margin:0 24px;text-align:center;position:relative;overflow:hidden}\n  .m37 .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#a06640;font-weight:700}\n  .m37 h3{margin-top:18px;font-size:clamp(40px,4.6vw,60px);font-weight:600;letter-spacing:-.03em;line-height:1.05}\n  .m37 h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m37 .ribbon{margin-top:48px;display:grid;grid-template-columns:repeat(4,1fr);gap:24px;text-align:left}\n  .m37 .item{padding:32px 24px;background:#fff;border-radius:20px;box-shadow:0 10px 30px rgba(29,29,31,.04);position:relative;overflow:hidden}\n  .m37 .item::after{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--brand-1)}\n  .m37 .item .v{font-family:\'Fraunces\',serif;font-weight:300;font-size:54px;letter-spacing:-.03em;line-height:1;color:var(--ink)}\n  .m37 .item .v em{font-style:italic;color:var(--brand-1)}\n  .m37 .item .lbl{margin-top:14px;font-size:13px;line-height:1.4;color:var(--ink-2);font-weight:500}\n  .m37 .item .lbl strong{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3);margin-bottom:4px}\n  @media(max-width:900px){.m37 .ribbon{grid-template-columns:repeat(2,1fr)}}\n\n  /* ----- M4.6 — Big editorial number with body ----- */\n  .m46{padding:0 24px;display:grid;grid-template-columns:1.3fr 1fr;gap:64px;align-items:center;max-width:1240px;margin:0 auto}\n  .m46 .num{font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(140px,18vw,260px);line-height:.85;letter-spacing:-.05em;color:var(--ink)}\n  .m46 .num em{font-style:italic;color:var(--brand-1)}\n  .m46 .num small{display:block;font-family:\'Inter\';font-size:13px;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-3);font-weight:700;margin-top:24px;letter-spacing:.18em}\n  .m46 .body h3{font-size:32px;font-weight:600;letter-spacing:-.022em;line-height:1.1}\n  .m46 .body h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .m46 .body p{margin-top:18px;font-size:17px;line-height:1.6;color:var(--ink-2);max-width:380px}\n  .m46 .body .cite{margin-top:24px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);font-weight:700}\n  @media(max-width:900px){.m46{grid-template-columns:1fr;gap:32px}}\n\n  /* ----- M4.7 — Mini-chart trio ----- */\n  .m47{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding:0 24px}\n  .m47 .card{background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px 28px;display:flex;flex-direction:column;gap:20px}\n  .m47 .card .ix{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3);font-weight:700}\n  .m47 .card h4{font-size:18px;font-weight:600;letter-spacing:-.012em;line-height:1.3}\n  .m47 .card h4 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m47 .card .v{font-family:\'Fraunces\',serif;font-weight:300;font-size:48px;letter-spacing:-.025em;color:var(--brand-1);line-height:1}\n  .m47 .card .v em{font-style:italic}\n  /* sparkline as svg-like bars */\n  .m47 .spark{display:flex;align-items:flex-end;gap:4px;height:60px}\n  .m47 .spark span{flex:1;background:linear-gradient(180deg,var(--brand-1),var(--brand-deep));border-radius:2px 2px 0 0;transition:height 1.2s cubic-bezier(.2,.8,.2,1);height:0}\n  .m47 .card.in .spark span{height:var(--h,40%)}\n  /* donut */\n  .m47 .donut{position:relative;width:120px;height:120px;border-radius:50%;background:conic-gradient(var(--brand-1) 0 var(--p,75%), #f1eee9 var(--p,75%) 100%);display:flex;align-items:center;justify-content:center}\n  .m47 .donut::after{content:"";position:absolute;inset:14px;background:#fff;border-radius:50%}\n  .m47 .donut span{position:relative;z-index:2;font-family:\'Fraunces\',serif;font-weight:300;font-size:28px;color:var(--ink);font-style:italic}\n  @media(max-width:900px){.m47{grid-template-columns:1fr}}\n\n  /* ----- M4.8 — Data ribbon (long horizontal stat strip) ----- */\n  .m48{padding:48px 56px;background:linear-gradient(135deg,var(--brand-soft) 0%,var(--brand-deep) 100%);border-radius:32px;margin:0 24px;color:#1f1411}\n  .m48 .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;opacity:.6}\n  .m48 h3{margin-top:14px;font-size:32px;font-weight:600;letter-spacing:-.025em;line-height:1.1;max-width:560px}\n  .m48 h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m48 .strip{margin-top:48px;display:grid;grid-template-columns:repeat(5,1fr);gap:0;border-top:1px solid rgba(31,20,17,.18)}\n  .m48 .cell{padding:24px 16px;border-right:1px solid rgba(31,20,17,.18)}\n  .m48 .cell:last-child{border-right:none}\n  .m48 .cell .v{font-family:\'Fraunces\',serif;font-weight:300;font-size:40px;letter-spacing:-.02em;line-height:1}\n  .m48 .cell .v em{font-style:italic}\n  .m48 .cell .l{margin-top:10px;font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;opacity:.7}\n  @media(max-width:900px){.m48 .strip{grid-template-columns:repeat(2,1fr)}.m48 .cell{border-bottom:1px solid rgba(31,20,17,.18)}}\n\n  /* ----- M5.6 — Pull-quote magazine stack ----- */\n  .m56{padding:0 24px;display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:1240px;margin:0 auto}\n  .m56 .q{padding:36px 32px;background:#fff;border-radius:24px;border:1px solid var(--line);display:flex;flex-direction:column;gap:20px;position:relative}\n  .m56 .q::before{content:"\\201C";font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;font-size:84px;color:var(--brand-1);line-height:.6;position:absolute;top:18px;left:24px;opacity:.2}\n  .m56 .q .text{position:relative;z-index:1;font-family:\'Fraunces\',serif;font-weight:300;font-size:22px;line-height:1.35;letter-spacing:-.012em;color:var(--ink)}\n  .m56 .q .text em{font-style:italic;color:var(--brand-1)}\n  .m56 .q .by{display:flex;align-items:center;gap:12px;margin-top:auto;padding-top:20px;border-top:1px solid var(--line)}\n  .m56 .q .av{width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,var(--brand-soft),var(--brand-deep));flex-shrink:0;display:flex;align-items:center;justify-content:center;font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:#7a3a1f}\n  .m56 .q .meta{display:flex;flex-direction:column;gap:2px}\n  .m56 .q .meta .name{font-size:14px;font-weight:600;letter-spacing:-.005em}\n  .m56 .q .meta .role{font-size:11px;color:var(--ink-3);letter-spacing:.06em}\n  @media(max-width:900px){.m56{grid-template-columns:1fr}}\n\n  /* ----- M5.7 — Single big testimonial w/ portrait ----- */\n  .m57{display:grid;grid-template-columns:1fr 1.2fr;gap:0;background:#fff;border-radius:32px;overflow:hidden;margin:0 24px;box-shadow:0 30px 80px rgba(29,29,31,.06);min-height:560px}\n  .m57 .portrait{position:relative;background:#1a1a1f;overflow:hidden}\n  .m57 .portrait img{width:100%;height:100%;object-fit:cover;opacity:.92}\n  .m57 .portrait .badge{position:absolute;top:24px;left:24px;padding:8px 14px;background:#fff;border-radius:999px;font-size:11px;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--ink)}\n  .m57 .body{padding:64px 56px;display:flex;flex-direction:column;justify-content:center;gap:24px}\n  .m57 .body .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#a06640;font-weight:700}\n  .m57 .body .text{font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(28px,3.2vw,42px);line-height:1.2;letter-spacing:-.022em;color:var(--ink)}\n  .m57 .body .text em{font-style:italic;color:var(--brand-1)}\n  .m57 .body .by{font-size:13px;letter-spacing:.06em;color:var(--ink-3);font-weight:500;padding-top:18px;border-top:1px solid var(--line)}\n  .m57 .body .by strong{font-weight:700;color:var(--ink);display:block;margin-bottom:2px;letter-spacing:0;font-size:15px}\n  @media(max-width:900px){.m57{grid-template-columns:1fr}.m57 .portrait{min-height:380px}.m57 .body{padding:40px 28px}}\n\n  /* ----- M5.8 — Star-rating ledger ----- */\n  .m58{padding:0 24px;max-width:920px;margin:0 auto}\n  .m58 .summary{padding:36px 40px;background:#0e0e10;color:#fff;border-radius:24px;display:grid;grid-template-columns:auto 1fr auto;gap:36px;align-items:center}\n  .m58 .summary .big{font-family:\'Fraunces\',serif;font-weight:300;font-size:80px;letter-spacing:-.03em;line-height:1}\n  .m58 .summary .big em{font-style:italic;color:var(--brand-1)}\n  .m58 .summary .stars{display:flex;gap:4px;color:var(--brand-1);font-size:20px}\n  .m58 .summary .meta{font-size:12px;color:rgba(255,255,255,.65);letter-spacing:.06em;margin-top:8px}\n  .m58 .summary .bars{display:flex;flex-direction:column;gap:6px;min-width:200px}\n  .m58 .summary .bar{display:grid;grid-template-columns:auto 1fr auto;gap:8px;font-size:11px;color:rgba(255,255,255,.7);align-items:center;letter-spacing:.06em}\n  .m58 .summary .bar .track{height:4px;background:rgba(255,255,255,.12);border-radius:999px;overflow:hidden}\n  .m58 .summary .bar .fill{height:100%;background:var(--brand-1);border-radius:999px}\n  .m58 .ledger{margin-top:24px;display:flex;flex-direction:column;gap:0;border:1px solid var(--line);border-radius:24px;overflow:hidden;background:#fff}\n  .m58 .ledger .row{padding:24px 32px;display:grid;grid-template-columns:80px 1fr 120px;gap:24px;border-bottom:1px solid var(--line);align-items:center}\n  .m58 .ledger .row:last-child{border-bottom:none}\n  .m58 .ledger .row .stars{color:var(--brand-1);font-size:13px;letter-spacing:1px}\n  .m58 .ledger .row .text{font-size:15px;line-height:1.5;color:var(--ink)}\n  .m58 .ledger .row .text strong{display:block;font-size:13px;color:var(--ink-3);font-weight:600;letter-spacing:.04em;margin-bottom:4px}\n  .m58 .ledger .row .by{font-size:12px;color:var(--ink-3);letter-spacing:.04em;text-align:right}\n  .m58 .ledger .row .by em{font-style:normal;display:block;color:var(--ink);font-weight:600;letter-spacing:0;font-size:14px;margin-bottom:2px}\n  @media(max-width:760px){.m58 .summary{grid-template-columns:1fr;text-align:center}.m58 .summary .bars{min-width:auto}.m58 .ledger .row{grid-template-columns:1fr;gap:8px}.m58 .ledger .row .by{text-align:left}}\n\n  /* ============================================================ */\n  /* ===== FAVORITES — 5 hero variations the client loved ====== */\n  /* ============================================================ */\n\n  /* FAV.1 — Calendar grid hero ("82 women · 6 months · 1 device") */\n  .fav1{padding:120px 48px;background:#0e0e10;color:#fff;border-radius:32px;margin:0 24px;position:relative;overflow:hidden}\n  .fav1::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse 800px 400px at 50% 0%, rgba(255,156,112,.18), transparent 60%)}\n  .fav1 .head{position:relative;text-align:center;max-width:880px;margin:0 auto 80px}\n  .fav1 .head .ix{font-size:13px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.5);font-weight:600}\n  .fav1 .head h3{margin-top:18px;font-size:clamp(48px,6vw,84px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .fav1 .head h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .fav1 .grid{position:relative;display:grid;grid-template-columns:repeat(28,1fr);gap:6px;max-width:1100px;margin:0 auto}\n  .fav1 .cell{aspect-ratio:1;border-radius:3px;background:rgba(255,255,255,.06);transition:background .6s,transform .4s}\n  .fav1.in .cell{background:linear-gradient(135deg,var(--brand-1),var(--brand-deep));animation:fav1pop .8s cubic-bezier(.2,.7,.2,1) backwards}\n  .fav1 .cell.dim{background:rgba(255,255,255,.06) !important;animation:none}\n  @keyframes fav1pop{from{transform:scale(0);opacity:0}to{transform:scale(1);opacity:1}}\n  .fav1 .legend{position:relative;display:flex;justify-content:space-between;margin-top:48px;font-size:12px;color:rgba(255,255,255,.5);letter-spacing:.06em}\n  .fav1 .pull{position:relative;text-align:center;margin-top:48px;font-family:\'Fraunces\',serif;font-style:italic;font-size:21px;color:rgba(255,255,255,.7);max-width:560px;margin-left:auto;margin-right:auto;line-height:1.4}\n  @media(max-width:760px){.fav1{padding:64px 24px}.fav1 .grid{grid-template-columns:repeat(14,1fr)}}\n\n  /* FAV.2 — Topographic depth (concentric rings + layered text) */\n  .fav2{padding:140px 24px;background:#fff;border-radius:32px;margin:0 24px;position:relative;overflow:hidden;min-height:760px;display:flex;align-items:center;justify-content:center}\n  .fav2 .topo{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none}\n  .fav2 .topo svg{width:140%;height:140%;opacity:.5}\n  .fav2 .topo circle{fill:none;stroke:var(--brand-1);stroke-width:1;opacity:.18;transition:transform 1.6s cubic-bezier(.2,.7,.2,1),opacity 1.2s}\n  .fav2.in .topo circle{transform:scale(1)}\n  .fav2 .topo circle:nth-child(1){transform:scale(0);transition-delay:.05s}\n  .fav2 .topo circle:nth-child(2){transform:scale(0);transition-delay:.1s}\n  .fav2 .topo circle:nth-child(3){transform:scale(0);transition-delay:.15s}\n  .fav2 .topo circle:nth-child(4){transform:scale(0);transition-delay:.2s}\n  .fav2 .topo circle:nth-child(5){transform:scale(0);transition-delay:.25s}\n  .fav2 .topo circle:nth-child(6){transform:scale(0);transition-delay:.3s}\n  .fav2 .topo circle:nth-child(7){transform:scale(0);transition-delay:.35s}\n  .fav2 .topo circle:nth-child(8){transform:scale(0);transition-delay:.4s}\n  .fav2 .copy{position:relative;text-align:center;max-width:680px;z-index:2}\n  .fav2 .copy .ix{font-size:13px;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-3);font-weight:600}\n  .fav2 .copy h3{margin-top:24px;font-size:clamp(56px,7vw,100px);font-weight:600;letter-spacing:-.04em;line-height:1}\n  .fav2 .copy h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .fav2 .copy p{margin-top:36px;font-size:21px;line-height:1.5;color:var(--ink-2);max-width:520px;margin-left:auto;margin-right:auto}\n  .fav2 .depths{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:520px;margin:48px auto 0}\n  .fav2 .depth{padding:18px 14px;background:rgba(255,255,255,.7);backdrop-filter:blur(20px);border-radius:14px;border:1px solid rgba(0,0,0,.06)}\n  .fav2 .depth .num{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;font-size:32px;letter-spacing:-.02em;color:var(--brand-1)}\n  .fav2 .depth .lbl{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3);font-weight:600;margin-top:4px}\n\n  /* FAV.3 — Magazine cover style hero */\n  .fav3{display:grid;grid-template-columns:1.05fr 1fr;gap:0;background:#f5f1ea;border-radius:32px;overflow:hidden;margin:0 24px;min-height:680px;box-shadow:0 30px 80px rgba(29,29,31,.06)}\n  .fav3 .cover{position:relative;background:#0e0e10;overflow:hidden;padding:48px}\n  .fav3 .cover img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.92;transform:scale(1.2);transition:transform 4s cubic-bezier(.2,.7,.2,1)}\n  .fav3.in .cover img{transform:scale(1.05)}\n  .fav3 .cover::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.1) 0%,rgba(0,0,0,.5) 100%)}\n  .fav3 .masthead{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:flex-start;color:#fff;font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:600}\n  .fav3 .masthead .logo{font-family:\'Fraunces\',serif;font-style:italic;font-size:44px;font-weight:300;letter-spacing:-.02em;text-transform:none}\n  .fav3 .barcode{position:absolute;bottom:32px;left:48px;z-index:2;display:flex;gap:1px;align-items:flex-end;height:40px}\n  .fav3 .barcode span{display:block;width:2px;background:#fff}\n  .fav3 .issue{position:absolute;bottom:32px;right:48px;z-index:2;color:#fff;font-size:11px;letter-spacing:.16em;text-transform:uppercase;font-weight:600;text-align:right}\n  .fav3 .issue strong{display:block;font-family:\'Fraunces\',serif;font-weight:300;font-size:36px;font-style:italic;text-transform:none;letter-spacing:-.02em}\n  .fav3 .article{padding:64px 56px;display:flex;flex-direction:column;gap:24px;justify-content:center}\n  .fav3 .article .kicker{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#a06640;font-weight:700}\n  .fav3 .article h3{font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(44px,4.8vw,64px);line-height:1;letter-spacing:-.025em}\n  .fav3 .article h3 em{font-style:italic;font-weight:400}\n  .fav3 .article .lede{font-size:21px;line-height:1.5;color:var(--ink-2);font-weight:400;letter-spacing:-.005em}\n  .fav3 .article .lede::first-letter{font-family:\'Fraunces\',serif;font-size:64px;font-weight:300;float:left;line-height:.85;padding:6px 12px 0 0;color:var(--brand-1);font-style:italic}\n  .fav3 .article .by{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3);font-weight:600;margin-top:8px;padding-top:24px;border-top:1px solid rgba(0,0,0,.12)}\n  @media(max-width:900px){.fav3{grid-template-columns:1fr}.fav3 .cover{min-height:420px}.fav3 .article{padding:48px 28px}}\n\n  /* FAV.4 — Three-up macro tiles with hover scale */\n  .fav4{padding:0 24px}\n  .fav4 .head{text-align:center;max-width:760px;margin:0 auto 64px}\n  .fav4 .head .ix{font-size:13px;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-3);font-weight:600}\n  .fav4 .head h3{margin-top:18px;font-size:clamp(44px,5.5vw,72px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .fav4 .head h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .fav4 .tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}\n  .fav4 .tile{position:relative;border-radius:24px;overflow:hidden;aspect-ratio:3/4;background:#1a1a1f;cursor:pointer}\n  .fav4 .tile img{width:100%;height:100%;object-fit:cover;opacity:.85;transition:transform 1.2s cubic-bezier(.2,.7,.2,1),opacity .6s}\n  .fav4 .tile:hover img{transform:scale(1.08);opacity:1}\n  .fav4 .tile .gloss{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.05) 0%,rgba(0,0,0,.55) 60%,rgba(0,0,0,.85) 100%)}\n  .fav4 .tile .meta{position:absolute;top:24px;left:24px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.85);font-weight:600;display:flex;align-items:center;gap:8px}\n  .fav4 .tile .meta .dot{width:8px;height:8px;border-radius:50%;background:var(--brand-1);box-shadow:0 0 12px var(--brand-1)}\n  .fav4 .tile .body{position:absolute;bottom:24px;left:24px;right:24px;color:#fff}\n  .fav4 .tile .body .ttl{font-size:32px;font-weight:600;letter-spacing:-.022em;line-height:1.05}\n  .fav4 .tile .body .ttl em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .fav4 .tile .body p{margin-top:10px;font-size:15px;line-height:1.5;color:rgba(255,255,255,.78);max-width:280px}\n  .fav4 .tile .num{position:absolute;top:24px;right:24px;font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;font-size:48px;color:rgba(255,255,255,.85);line-height:1;letter-spacing:-.02em}\n  @media(max-width:900px){.fav4 .tiles{grid-template-columns:1fr}}\n\n  /* FAV.5 — Big number ribbon (vertical asymmetric) */\n  .fav5{padding:0 24px}\n  .fav5 .frame{display:grid;grid-template-columns:1fr 1.2fr;gap:0;background:#fff;border-radius:32px;overflow:hidden;box-shadow:0 30px 80px rgba(29,29,31,.05);min-height:720px}\n  .fav5 .left{background:linear-gradient(180deg,var(--brand-soft) 0%, var(--brand-deep) 60%, var(--brand-1) 100%);padding:64px 56px;display:flex;flex-direction:column;justify-content:space-between;color:#1f1411}\n  .fav5 .left .ix{font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:rgba(31,20,17,.6)}\n  .fav5 .left .heroNum{font-family:\'Fraunces\',serif;font-weight:300;font-size:clamp(120px,14vw,200px);line-height:.9;letter-spacing:-.04em}\n  .fav5 .left .heroNum em{font-style:italic}\n  .fav5 .left .sub{font-size:24px;line-height:1.3;letter-spacing:-.012em;font-weight:500;max-width:340px}\n  .fav5 .left .foot{font-size:12px;color:rgba(31,20,17,.55);letter-spacing:.06em}\n  .fav5 .right{padding:64px 48px;display:flex;flex-direction:column;justify-content:center;gap:0}\n  .fav5 .right .row{display:grid;grid-template-columns:80px 1fr 140px;gap:24px;align-items:center;padding:28px 0;border-bottom:1px solid var(--line)}\n  .fav5 .right .row:first-child{padding-top:0}\n  .fav5 .right .row:last-child{border-bottom:none;padding-bottom:0}\n  .fav5 .right .ix{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-4);font-weight:700;font-variant-numeric:tabular-nums}\n  .fav5 .right .ttl{font-size:21px;font-weight:600;letter-spacing:-.012em}\n  .fav5 .right .ttl em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--brand-1)}\n  .fav5 .right .ttl small{display:block;font-weight:400;font-size:14px;color:var(--ink-3);margin-top:4px;letter-spacing:0}\n  .fav5 .right .v{font-family:\'Fraunces\',serif;font-weight:300;font-size:36px;letter-spacing:-.02em;text-align:right;color:var(--ink)}\n  .fav5 .right .v em{font-style:normal;font-family:\'Inter\';font-size:14px;font-weight:500;color:var(--ink-3);margin-left:4px;letter-spacing:0}\n  @media(max-width:900px){.fav5 .frame{grid-template-columns:1fr}.fav5 .left{padding:48px 28px}.fav5 .right{padding:32px 28px}}\n\n  /* M2.6 — polaroid scrapbook */\n  .m26{padding:120px 24px;text-align:center;background:#fafafa;border-radius:32px;margin:0 24px;position:relative;overflow:hidden;min-height:680px}\n  .m26 .head{font-family:\'Fraunces\',serif;font-style:italic;font-size:clamp(36px,4.5vw,56px);font-weight:300;letter-spacing:-.022em;max-width:760px;margin:0 auto}\n  .m26 .head .ink{font-style:normal;font-family:\'Inter\';font-weight:600}\n  .m26 .polaroids{position:relative;height:520px;margin-top:48px}\n  .m26 .pol{position:absolute;background:#fff;padding:14px 14px 56px;border-radius:6px;box-shadow:0 30px 60px rgba(29,29,31,.15);transition:transform .5s cubic-bezier(.2,.7,.2,1)}\n  .m26 .pol:hover{z-index:5;transform:rotate(0deg) scale(1.06) !important}\n  .m26 .pol .img{width:240px;height:280px;background:#f5f5f7;border-radius:2px;overflow:hidden}\n  .m26 .pol .img img{width:100%;height:100%;object-fit:cover}\n  .m26 .pol .cap{margin-top:14px;font-family:\'Fraunces\',serif;font-style:italic;font-size:18px;color:var(--ink)}\n  .m26 .pol.p1{top:20px;left:18%;transform:rotate(-6deg)}\n  .m26 .pol.p2{top:60px;left:42%;transform:rotate(3deg);z-index:2}\n  .m26 .pol.p3{top:100px;right:16%;transform:rotate(-4deg)}\n  @media(max-width:900px){.m26 .pol{position:relative;display:inline-block;margin:8px;top:auto !important;left:auto !important;right:auto !important}.m26 .polaroids{height:auto}}\n\n  /* ===================== M3 — FEATURE SPOTLIGHT ===================== */\n  /* M3.1 — TAKE A CLOSER LOOK style scroll-driven product */\n  .m31-stage{position:relative;height:300vh}\n  .m31-pin{position:sticky;top:0;height:100vh;display:flex;align-items:center;justify-content:center;overflow:hidden}\n  .m31-product{\n    position:relative;width:60vw;max-width:560px;aspect-ratio:1;\n    border-radius:50%;\n    background:radial-gradient(circle at 35% 30%, #fff 0%, #f0e3da 50%, #d8b8a0 100%);\n    box-shadow:0 60px 120px rgba(29,29,31,.12);\n    transition:transform .1s linear;\n    display:flex;align-items:center;justify-content:center;\n  }\n  .m31-product::after{\n    content:"";position:absolute;inset:18%;border-radius:50%;\n    background:radial-gradient(circle at 40% 30%, #ffd4a8 0%, #ff9c70 60%, #d96644 100%);\n    opacity:.85;\n  }\n  .m31-product img{\n    position:relative;z-index:2;width:65%;height:65%;object-fit:contain;filter:drop-shadow(0 20px 40px rgba(29,29,31,.2));\n  }\n  .m31-hotspot{\n    position:absolute;width:36px;height:36px;border-radius:50%;\n    background:rgba(255,255,255,.95);backdrop-filter:blur(10px);\n    display:flex;align-items:center;justify-content:center;\n    cursor:pointer;\n    box-shadow:0 6px 16px rgba(29,29,31,.15);\n    transform:scale(0);transition:transform .5s cubic-bezier(.2,.7,.2,1);\n    z-index:5;\n  }\n  .m31-hotspot::before{content:"+";font-size:22px;color:var(--ink);font-weight:300}\n  .m31-hotspot::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:2px solid rgba(255,255,255,.6);animation:pulseHs 2.4s ease-out infinite}\n  @keyframes pulseHs{0%{transform:scale(.9);opacity:1}100%{transform:scale(1.6);opacity:0}}\n  .m31-stage.expanded .m31-hotspot{transform:scale(1)}\n  .m31-hs1{top:18%;left:50%}\n  .m31-hs2{top:50%;left:14%}\n  .m31-hs3{top:50%;right:14%}\n  .m31-hs4{bottom:18%;left:50%}\n\n  .m31-text{position:absolute;text-align:center;color:var(--ink);padding:0 32px;width:100%;max-width:900px;left:50%;transform:translateX(-50%);transition:opacity .8s, transform .8s cubic-bezier(.2,.7,.2,1);pointer-events:none}\n  .m31-text.intro{top:12%}\n  .m31-text.outro{bottom:12%;opacity:0;transform:translateX(-50%) translateY(20px)}\n  .m31-stage.expanded .m31-text.outro{opacity:1;transform:translateX(-50%) translateY(0)}\n  .m31-stage.expanded .m31-text.intro{opacity:0;transform:translateX(-50%) translateY(-20px)}\n  .m31-text .ix{font-size:14px;font-weight:600;color:var(--ink-3);letter-spacing:-.005em}\n  .m31-text h3{margin-top:14px;font-size:clamp(40px,6vw,80px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .m31-text h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m31-scrollhint{position:absolute;bottom:32px;left:50%;transform:translateX(-50%);font-size:12px;color:var(--ink-4);letter-spacing:.1em;text-transform:uppercase;display:flex;flex-direction:column;align-items:center;gap:8px}\n  .m31-scrollhint .ar{width:1px;height:24px;background:linear-gradient(180deg,var(--ink-4),transparent);animation:bobble 2s ease-in-out infinite}\n\n  /* M3.2 — feature cards with peach gradient */\n  .m32{padding:120px 24px;background:var(--grad-peach);border-radius:32px;margin:0 24px}\n  .m32 .head{text-align:center;margin-bottom:80px;color:var(--ink)}\n  .m32 .head .ix{font-size:17px;font-weight:600;color:#7a4530}\n  .m32 .head h3{margin-top:8px;font-size:clamp(48px,6.5vw,84px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .m32 .head h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m32 .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:1200px;margin:0 auto}\n  .m32 .card{background:rgba(255,255,255,.7);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-radius:24px;padding:40px;display:flex;flex-direction:column;gap:18px;min-height:380px;transition:transform .4s, background .4s}\n  .m32 .card:hover{transform:translateY(-4px);background:rgba(255,255,255,.9)}\n  .m32 .card .glyph{width:56px;height:56px;border-radius:16px;background:linear-gradient(135deg,#ff9c70,#d96644);display:flex;align-items:center;justify-content:center;color:#fff;font-family:\'Fraunces\',serif;font-style:italic;font-size:24px}\n  .m32 .card h4{font-size:28px;font-weight:600;letter-spacing:-.022em;line-height:1.1}\n  .m32 .card h4 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:400}\n  .m32 .card p{font-size:17px;line-height:1.5;color:var(--ink-2);margin-top:auto}\n  .m32 .card .meta{font-size:12px;font-weight:600;letter-spacing:.06em;color:#7a4530;text-transform:uppercase}\n  @media(max-width:900px){.m32 .grid{grid-template-columns:1fr}}\n\n  /* M3.3 — exploded view */\n  .m33{padding:160px 24px;background:#fafafa;text-align:center;border-radius:32px;margin:0 24px;position:relative;overflow:hidden;min-height:700px}\n  .m33 .head{margin-bottom:64px}\n  .m33 .head .ix{font-size:17px;font-weight:600;color:var(--ink-2)}\n  .m33 .head h3{margin-top:8px;font-size:clamp(40px,6vw,72px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .m33 .head h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m33 .stage-x{position:relative;width:100%;height:520px;display:flex;align-items:center;justify-content:center}\n  .m33 .core{\n    position:relative;width:280px;height:280px;border-radius:50%;\n    background:radial-gradient(circle at 35% 30%, #fff, #f0e3da 50%, #d8b8a0 100%);\n    box-shadow:0 30px 80px rgba(29,29,31,.15);\n    z-index:3;\n    transform:scale(.8);transition:transform 1.4s cubic-bezier(.2,.7,.2,1)}\n  .m33.in .core{transform:scale(1)}\n  .m33 .core::after{content:"";position:absolute;inset:24px;border-radius:50%;background:linear-gradient(135deg,#ff9c70,#d96644)}\n  .m33 .part{\n    position:absolute;background:#fff;border-radius:18px;padding:20px;\n    width:180px;text-align:left;z-index:5;\n    box-shadow:0 14px 40px rgba(29,29,31,.08);\n    transform:scale(.5) translate(0,0);opacity:0;\n    transition:transform 1.4s cubic-bezier(.2,.7,.2,1), opacity 1.2s;\n  }\n  .m33.in .part{opacity:1;transform:scale(1) translate(0,0)}\n  .m33 .part .lbl{font-size:11px;font-weight:600;letter-spacing:.16em;color:var(--ink-3);text-transform:uppercase}\n  .m33 .part .ttl{font-size:18px;font-weight:600;margin-top:6px;letter-spacing:-.014em}\n  .m33 .part .desc{font-size:13px;color:var(--ink-2);margin-top:6px;line-height:1.4}\n  .m33 .part.p1{top:8%;left:18%;transition-delay:.2s}\n  .m33 .part.p2{top:14%;right:18%;transition-delay:.35s}\n  .m33 .part.p3{bottom:14%;left:14%;transition-delay:.5s}\n  .m33 .part.p4{bottom:8%;right:14%;transition-delay:.65s}\n  .m33 svg.lines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}\n  .m33 svg.lines path{stroke:var(--ink-4);stroke-width:1;fill:none;stroke-dasharray:400;stroke-dashoffset:400;transition:stroke-dashoffset 1.6s cubic-bezier(.2,.7,.2,1) .8s}\n  .m33.in svg.lines path{stroke-dashoffset:0}\n\n  /* M3.4 — macro grid 2-col */\n  .m34{display:grid;grid-template-columns:1fr 1fr;gap:0;background:#fff;border-radius:32px;overflow:hidden;min-height:600px;margin:0 24px;box-shadow:0 30px 80px rgba(29,29,31,.04)}\n  .m34 .macro{position:relative;background:#1a1a1f;overflow:hidden}\n  .m34 .macro img{width:100%;height:100%;object-fit:cover;transform:scale(1.4);transition:transform 4s cubic-bezier(.2,.7,.2,1)}\n  .m34.in .macro img{transform:scale(1.1)}\n  .m34 .macro .corner{position:absolute;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.4);font-weight:500}\n  .m34 .macro .c-tl{top:24px;left:24px}\n  .m34 .macro .c-br{bottom:24px;right:24px}\n  .m34 .copy{padding:80px 64px;display:flex;flex-direction:column;justify-content:center;gap:24px}\n  .m34 .ix{font-size:14px;font-weight:600;color:var(--ink-3)}\n  .m34 h3{font-size:clamp(36px,4.5vw,60px);font-weight:600;letter-spacing:-.028em;line-height:1.02}\n  .m34 h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m34 p{font-size:19px;line-height:1.5;color:var(--ink-2)}\n  .m34 .specs{display:grid;grid-template-columns:1fr 1fr;gap:24px;border-top:1px solid var(--line);padding-top:32px;margin-top:8px}\n  .m34 .spec .l{font-size:11px;letter-spacing:.16em;color:var(--ink-3);text-transform:uppercase;font-weight:600}\n  .m34 .spec .v{font-family:\'Fraunces\',serif;font-size:32px;font-weight:300;margin-top:6px;letter-spacing:-.02em}\n  @media(max-width:900px){.m34{grid-template-columns:1fr}.m34 .copy{padding:48px 32px}}\n\n  /* M3.5 — depth-card stack */\n  .m35{padding:120px 24px;background:var(--grad-sky);border-radius:32px;margin:0 24px;text-align:center}\n  .m35 .head{margin-bottom:80px}\n  .m35 .head .ix{font-size:17px;font-weight:600;color:#345580}\n  .m35 .head h3{margin-top:8px;font-size:clamp(48px,6.5vw,84px);font-weight:600;letter-spacing:-.035em;line-height:1}\n  .m35 .head h3 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m35 .stack{position:relative;height:480px;max-width:600px;margin:0 auto;perspective:1200px}\n  .m35 .layer{\n    position:absolute;inset:0;border-radius:24px;background:rgba(255,255,255,.85);backdrop-filter:blur(20px);\n    box-shadow:0 30px 60px rgba(29,29,31,.1);\n    padding:40px;display:flex;flex-direction:column;justify-content:center;text-align:left;\n    transition:transform 1s cubic-bezier(.2,.7,.2,1);\n  }\n  .m35.in .layer.l1{transform:translateY(-60px) translateX(-40px) rotateZ(-3deg)}\n  .m35.in .layer.l2{transform:translateY(-30px) translateX(-20px) rotateZ(-1.5deg)}\n  .m35.in .layer.l3{transform:translateY(0) translateX(0) rotateZ(0deg)}\n  .m35 .layer.l1{z-index:1;background:rgba(255,255,255,.6)}\n  .m35 .layer.l2{z-index:2;background:rgba(255,255,255,.75)}\n  .m35 .layer.l3{z-index:3}\n  .m35 .layer .ix{font-size:11px;font-weight:600;letter-spacing:.16em;color:var(--ink-3);text-transform:uppercase}\n  .m35 .layer h4{margin-top:14px;font-size:36px;font-weight:600;letter-spacing:-.025em;line-height:1.05}\n  .m35 .layer h4 em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300}\n  .m35 .layer p{margin-top:18px;font-size:17px;line-height:1.5;color:var(--ink-2)}\n\n  /* ===================== MODULE 4: FACTS ===================== */\n  .m4-bg{background:linear-gradient(180deg,#fff 0%,#fff8f3 100%)}\n\n  /* M4.1 — Big numbers grid with counter animation */\n  .m41{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-top:1px solid var(--line);max-width:1280px;margin:0 auto}\n  .m41 .cell{padding:48px 24px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:14px;min-width:0}\n  .m41 .cell:nth-child(4n){border-right:0}\n  .m41 .ix{font-size:11px;font-weight:600;letter-spacing:.18em;color:var(--ink-3);text-transform:uppercase}\n  .m41 .num{font-size:80px;font-weight:200;letter-spacing:-.04em;line-height:.95;color:var(--ink);white-space:nowrap}\n  .m41 .num em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--accent);font-size:40px;vertical-align:top;margin-left:4px}\n  .m41 .lbl{font-size:14px;line-height:1.5;color:var(--ink-2)}\n  @media(max-width:960px){.m41{grid-template-columns:repeat(2,1fr)}.m41 .cell:nth-child(4n){border-right:1px solid var(--line)}.m41 .cell:nth-child(2n){border-right:0}}\n\n  /* M4.2 — Horizontal scroll facts */\n  .m42{padding:32px 0}\n  .m42 .track{display:flex;gap:24px;padding:0 24px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}\n  .m42 .track::-webkit-scrollbar{display:none}\n  .m42 .card{flex:0 0 380px;scroll-snap-align:start;background:#fff;border-radius:28px;padding:40px;box-shadow:0 1px 0 rgba(0,0,0,.04),0 16px 48px -16px rgba(0,0,0,.08);display:flex;flex-direction:column;gap:18px;min-height:380px}\n  .m42 .card .ix{font-size:11px;font-weight:600;letter-spacing:.18em;color:var(--ink-3);text-transform:uppercase}\n  .m42 .card .big{font-size:88px;font-weight:200;letter-spacing:-.04em;line-height:.9;margin-top:auto}\n  .m42 .card .big em{font-family:\'Fraunces\',serif;font-style:italic;color:var(--accent);font-size:48px}\n  .m42 .card h4{font-size:24px;font-weight:600;letter-spacing:-.02em;line-height:1.15}\n  .m42 .card p{font-size:15px;line-height:1.5;color:var(--ink-2)}\n\n  /* M4.3 — Stat with photo split */\n  .m43{display:grid;grid-template-columns:1fr 1fr;gap:0;border-radius:32px;overflow:hidden;background:#0e1418;color:#fff;max-width:1280px;margin:0 auto;min-height:560px}\n  .m43 .left{padding:80px;display:flex;flex-direction:column;justify-content:space-between;gap:32px}\n  .m43 .left .ix{font-size:11px;font-weight:600;letter-spacing:.18em;color:rgba(255,255,255,.5);text-transform:uppercase}\n  .m43 .left .stat{font-size:200px;font-weight:200;letter-spacing:-.05em;line-height:.85}\n  .m43 .left .stat em{font-family:\'Fraunces\',serif;font-style:italic;color:#ff9c70;font-size:96px;vertical-align:top}\n  .m43 .left p{font-size:18px;line-height:1.5;color:rgba(255,255,255,.75);max-width:380px}\n  .m43 .right{position:relative;overflow:hidden}\n  .m43 .right img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(.8)}\n\n  /* M4.4 — Comparison bar chart */\n  .m44{max-width:1080px;margin:0 auto;padding:64px 0}\n  .m44 .row{display:grid;grid-template-columns:200px 1fr 100px;gap:32px;align-items:center;padding:24px 0;border-bottom:1px solid var(--line)}\n  .m44 .row:last-child{border-bottom:0}\n  .m44 .row .lbl{font-size:18px;font-weight:500;letter-spacing:-.01em}\n  .m44 .row .lbl em{font-family:\'Fraunces\',serif;font-style:italic;color:var(--accent)}\n  .m44 .row .bar-wrap{height:14px;background:#f4f6f8;border-radius:999px;overflow:hidden;position:relative;display:block}\n  .m44 .row .bar{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#ff9c70,#ffd6c2);width:0;transition:width 1.4s cubic-bezier(.2,.8,.2,1)}\n  .m44 .row.in .bar{width:var(--w,50%)}\n  .m44 .row.alt .bar{background:#d8dee5}\n  .m44 .row .v{font-size:18px;font-weight:600;letter-spacing:-.01em;text-align:right;font-variant-numeric:tabular-nums}\n  .m44 .row .v em{font-family:\'Fraunces\',serif;font-style:italic;color:var(--accent);font-weight:300}\n\n  /* M4.5 — Animated ticker */\n  .m45{overflow:hidden;background:#0e1418;color:#fff;padding:80px 0;border-radius:32px;max-width:calc(100% - 48px);margin:0 auto}\n  .m45 .head{text-align:center;margin-bottom:48px;padding:0 24px}\n  .m45 .head h3{font-size:56px;font-weight:200;letter-spacing:-.025em;line-height:1.05}\n  .m45 .head h3 em{font-family:\'Fraunces\',serif;font-style:italic;color:#ff9c70}\n  .m45 .ticker{display:flex;gap:80px;animation:tick 40s linear infinite;width:max-content}\n  .m45 .ticker .item{display:flex;align-items:baseline;gap:16px;white-space:nowrap}\n  .m45 .ticker .n{font-size:88px;font-weight:200;letter-spacing:-.04em;line-height:1;color:#ff9c70;font-family:\'Fraunces\',serif;font-style:italic}\n  .m45 .ticker .t{font-size:24px;font-weight:500;color:rgba(255,255,255,.85)}\n  .m45 .ticker .dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.2);align-self:center}\n  @keyframes tick{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n\n  /* ===================== MODULE 5: REVIEWS ===================== */\n  .m5-bg{background:#f4f6f8}\n\n  /* M5.1 — Glass cards on gradient */\n  .m51-stage{position:relative;padding:80px 24px;background:linear-gradient(135deg,#ffd6c2 0%,#ffb89e 40%,#c9b6f5 100%);border-radius:32px;max-width:calc(100% - 48px);margin:0 auto;overflow:hidden}\n  .m51-stage::before{content:"";position:absolute;width:600px;height:600px;background:radial-gradient(circle,rgba(255,255,255,.6),transparent);top:-200px;right:-200px;border-radius:50%}\n  .m51-stage::after{content:"";position:absolute;width:500px;height:500px;background:radial-gradient(circle,rgba(255,255,255,.4),transparent);bottom:-100px;left:-100px;border-radius:50%}\n  .m51-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:1280px;margin:0 auto;position:relative;z-index:1}\n  .m51 .card{background:rgba(255,255,255,.55);backdrop-filter:blur(24px) saturate(150%);-webkit-backdrop-filter:blur(24px) saturate(150%);border:1px solid rgba(255,255,255,.6);border-radius:24px;padding:32px;display:flex;flex-direction:column;gap:20px;box-shadow:0 16px 48px -16px rgba(0,0,0,.15)}\n  .m51 .card .stars{color:#ff9c70;font-size:14px;letter-spacing:2px}\n  .m51 .card blockquote{font-size:20px;font-weight:500;letter-spacing:-.015em;line-height:1.35;color:var(--ink)}\n  .m51 .card blockquote em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:400}\n  .m51 .card .who{display:flex;align-items:center;gap:12px;margin-top:auto;padding-top:20px;border-top:1px solid rgba(0,0,0,.08)}\n  .m51 .card .ava{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#ff9c70,#ffd6c2);display:flex;align-items:center;justify-content:center;font-weight:600;color:#fff;font-size:15px;flex-shrink:0}\n  .m51 .card .name{font-size:14px;font-weight:600}\n  .m51 .card .meta{font-size:12px;color:var(--ink-3)}\n\n  /* M5.2 — Single big quote with rotation */\n  .m52{max-width:1080px;margin:0 auto;text-align:center;padding:80px 24px}\n  .m52 .stars{color:#ff9c70;font-size:18px;letter-spacing:4px;margin-bottom:32px}\n  .m52 blockquote{font-size:64px;font-weight:200;letter-spacing:-.025em;line-height:1.05;color:var(--ink)}\n  .m52 blockquote em{font-family:\'Fraunces\',serif;font-style:italic;font-weight:300;color:var(--accent)}\n  .m52 .author{display:inline-flex;align-items:center;gap:14px;margin-top:48px;padding:14px 24px;background:#fff;border-radius:999px;box-shadow:0 4px 16px rgba(0,0,0,.06)}\n  .m52 .author .ava{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,#ff9c70,#ffd6c2)}\n  .m52 .author .name{font-size:14px;font-weight:600}\n  .m52 .author .meta{font-size:12px;color:var(--ink-3)}\n  .m52 .dots{display:flex;gap:8px;justify-content:center;margin-top:32px}\n  .m52 .dots span{width:8px;height:8px;border-radius:50%;background:#d8dee5}\n  .m52 .dots span.on{background:var(--ink)}\n\n  /* M5.3 — Magazine pull quotes */\n  .m53{display:grid;grid-template-columns:repeat(2,1fr);gap:24px;max-width:1280px;margin:0 auto}\n  .m53 .pull{background:#fff;border-radius:28px;padding:48px;display:flex;flex-direction:column;gap:24px;border:1px solid var(--line);position:relative;overflow:hidden}\n  .m53 .pull::before{content:"";position:absolute;font-family:\'Fraunces\',serif;font-size:240px;font-style:italic;color:#ff9c70;opacity:.15;top:-80px;left:-20px;line-height:1}\n  .m53 .pull.q1::before{content:""}\n  .m53 .pull .mag{font-size:11px;font-weight:600;letter-spacing:.18em;color:var(--ink-3);text-transform:uppercase;position:relative;z-index:1}\n  .m53 .pull blockquote{font-size:32px;font-weight:300;letter-spacing:-.02em;line-height:1.2;position:relative;z-index:1}\n  .m53 .pull blockquote em{font-family:\'Fraunces\',serif;font-style:italic;color:var(--accent)}\n  .m53 .pull .by{font-size:13px;color:var(--ink-3);margin-top:auto;position:relative;z-index:1}\n\n  /* M5.4 — Vertical scroll wall */\n  .m54{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:1280px;margin:0 auto;height:680px;overflow:hidden;mask-image:linear-gradient(180deg,transparent 0,#000 12%,#000 88%,transparent 100%)}\n  .m54 .col{display:flex;flex-direction:column;gap:20px;animation:scroll-up 40s linear infinite}\n  .m54 .col.c2{animation-duration:50s;animation-direction:reverse}\n  .m54 .col.c3{animation-duration:60s}\n  @keyframes scroll-up{from{transform:translateY(0)}to{transform:translateY(-50%)}}\n  .m54 .mini{background:#fff;border-radius:20px;padding:24px;border:1px solid var(--line);display:flex;flex-direction:column;gap:12px;flex-shrink:0}\n  .m54 .mini .stars{color:#ff9c70;font-size:11px;letter-spacing:2px}\n  .m54 .mini p{font-size:15px;line-height:1.4;color:var(--ink)}\n  .m54 .mini p em{font-family:\'Fraunces\',serif;font-style:italic}\n  .m54 .mini .who{font-size:12px;color:var(--ink-3)}\n\n  /* M5.5 — Stat-driven testimonial */\n  .m55{display:grid;grid-template-columns:1fr 1fr;gap:0;background:#fff;border-radius:32px;overflow:hidden;max-width:1280px;margin:0 auto;border:1px solid var(--line);min-height:520px}\n  .m55 .photo{position:relative;background:#f4f6f8;overflow:hidden}\n  .m55 .photo img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n  .m55 .photo .badge{position:absolute;top:24px;left:24px;background:rgba(255,255,255,.95);padding:10px 16px;border-radius:999px;font-size:11px;font-weight:600;letter-spacing:.16em;text-transform:uppercase}\n  .m55 .copy{padding:64px 56px;display:flex;flex-direction:column;gap:24px;justify-content:center}\n  .m55 .copy .ix{font-size:11px;font-weight:600;letter-spacing:.18em;color:var(--ink-3);text-transform:uppercase}\n  .m55 .copy blockquote{font-size:28px;font-weight:300;letter-spacing:-.02em;line-height:1.25}\n  .m55 .copy blockquote em{font-family:\'Fraunces\',serif;font-style:italic;color:var(--accent)}\n  .m55 .stats-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;padding-top:24px;border-top:1px solid var(--line)}\n  .m55 .stats-row .v{font-size:42px;font-weight:200;letter-spacing:-.03em;line-height:1}\n  .m55 .stats-row .v em{font-family:\'Fraunces\',serif;font-style:italic;color:var(--accent);font-size:24px}\n  .m55 .stats-row .l{font-size:11px;font-weight:600;letter-spacing:.16em;color:var(--ink-3);text-transform:uppercase;margin-top:6px}\n  .m55 .who{display:flex;align-items:center;gap:14px}\n  .m55 .who .ava{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#ff9c70,#ffd6c2);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:600}\n\n  /* ===================== FOOTER ===================== */\n  .ft{padding:80px 24px;background:#fafafa;text-align:center;border-top:1px solid var(--line)}\n  .ft .row{max-width:1280px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap}\n  .ft .brand{display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px}\n  .ft .brand .mark{width:18px;height:18px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#fff,#ffd6c2 60%,#ff9c70)}\n  .ft .links{display:flex;gap:24px;font-size:13px;color:var(--ink-3)}\n  .ft .copy{font-size:12px;color:var(--ink-4)}\n\n  @media(max-width:760px){\n    .module{padding:100px 16px}\n    .module-head h2{font-size:48px}\n    .story-row .copy{padding:48px 24px}\n  }\n'


